function saudacao(prefixo) {
  return `${prefixo}, ${this.nome}!`;
}

console.log(saudacao.call({ nome: 'Ana' }, 'Olá'));   // Olá, Ana!
console.log(saudacao.apply({ nome: 'Bia' }, ['Oi'])); // Oi, Bia!

const saudarCauê = saudacao.bind({ nome: 'Cauê' }, 'Bom dia');
console.log(saudarCauê()); // Bom dia, Cauê!

// A original não mudou e a nova não quebra ao ser chamada de novo:
console.log(saudacao.call({ nome: 'Duda' }, 'Olá')); // Olá, Duda!
console.log(saudarCauê()); // Bom dia, Cauê! (this continua fixo)

// Passo 1: função genérica — só usa o this (nome e idade).
function apresentar(prefixo) {
  return `${prefixo} ${this.nome}, ${this.idade} anos`;
}

// Passo 2: objetos de dados, sem métodos.
const cliente = { nome: 'Ana', idade: 30 };
const funcionario = { nome: 'Bia', idade: 25 };

// Passo 3: call — chamada pontual, this escolhido na hora.
console.log(apresentar.call(cliente, 'Cliente:'));      // Cliente: Ana, 30 anos
console.log(apresentar.call(funcionario, 'Funcionária:')); // Funcionária: Bia, 25 anos

// Passo 4: bind — funções prontas, this fixado para sempre.
const apresentarAna = apresentar.bind(cliente, 'Cliente:');
const apresentarBia = apresentar.bind(funcionario, 'Funcionária:');
console.log(apresentarAna()); // Cliente: Ana, 30 anos
console.log(apresentarBia()); // Funcionária: Bia, 25 anos

// Passo 5: a original continua funcionando com qualquer this.
console.log(apresentar.call({ nome: 'Cauê', idade: 18 }, 'Visitante:')); // Visitante: Cauê, 18 anos
